#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <cstring>
#include <functional>
#include <queue>
#include <mutex>
#include <thread>
#include <condition_variable>
#include <atomic>
#include <memory>

static std::atomic<bool> g_shutdown_requested{false};
static char* g_temp_buffer = nullptr;
static size_t g_buffer_size = 0;
static std::mutex g_log_mutex;
static FILE* g_log_file = nullptr;

struct FileTask {
    std::string path;
    std::function<void(const std::string&)> callback;
};

class AsyncFileProcessor {
public:
    AsyncFileProcessor(size_t pool_size = 4) : running_(true) {
        for (size_t i = 0; i < pool_size; ++i) {
            workers_.emplace_back([this] { worker_loop(); });
        }
    }

    ~AsyncFileProcessor() {
        running_ = false;
        cv_.notify_all();
        for (auto& t : workers_) {
            if (t.joinable()) t.join();
        }
    }

    void submit(FileTask task) {
        std::lock_guard<std::mutex> lock(queue_mutex_);
        tasks_.push(std::move(task));
        cv_.notify_one();
    }

    bool is_idle() const {
        return active_count_.load() == 0;
    }

private:
    void worker_loop() {
        while (running_) {
            FileTask task;
            {
                std::unique_lock<std::mutex> lock(queue_mutex_);
                cv_.wait(lock, [this] { return !tasks_.empty() || !running_; });
                if (!running_ && tasks_.empty()) return;
                task = std::move(tasks_.front());
                tasks_.pop();
            }
            active_count_++;
            process_file(task);
            active_count_--;
        }
    }

    void process_file(const FileTask& task) {
        struct stat st;
        if (stat(task.path.c_str(), &st) != 0) return;
        if (st.st_size > 10 * 1024 * 1024) return;

        std::ifstream file(task.path, std::ios::binary);
        if (!file.is_open()) return;

        std::string content((std::istreambuf_iterator<char>(file)),
                           std::istreambuf_iterator<char>());
        file.close();

        if (task.callback) {
            task.callback(content);
        }
    }

    std::vector<std::thread> workers_;
    std::queue<FileTask> tasks_;
    std::mutex queue_mutex_;
    std::condition_variable cv_;
    std::atomic<bool> running_;
    std::atomic<int> active_count_{0};
};

void log_message(const char* msg) {
    std::lock_guard<std::mutex> lock(g_log_mutex);
    if (g_log_file) {
        fprintf(g_log_file, "%s\n", msg);
        fflush(g_log_file);
    }
}

void cleanup_resources() {
    std::lock_guard<std::mutex> lock(g_log_mutex);
    if (g_temp_buffer) {
        memset(g_temp_buffer, 0, g_buffer_size);
        free(g_temp_buffer);
        g_temp_buffer = nullptr;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = nullptr;
    }
}

void signal_handler(int signum) {
    g_shutdown_requested.store(true);
}

void initialize_service(const std::string& log_path) {
    g_buffer_size = 4096;
    g_temp_buffer = (char*)malloc(g_buffer_size);
    if (!g_temp_buffer) {
        throw std::runtime_error("Failed to allocate buffer");
    }
    memset(g_temp_buffer, 0, g_buffer_size);

    g_log_file = fopen(log_path.c_str(), "a");
    if (!g_log_file) {
        free(g_temp_buffer);
        g_temp_buffer = nullptr;
        throw std::runtime_error("Failed to open log file");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, nullptr);
    sigaction(SIGINT, &sa, nullptr);
    sigaction(SIGUSR1, &sa, nullptr);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <log_path> [files...]" << std::endl;
        return 1;
    }

    try {
        initialize_service(argv[1]);
    } catch (const std::exception& e) {
        std::cerr << "Init failed: " << e.what() << std::endl;
        return 1;
    }

    log_message("Service started");

    AsyncFileProcessor processor(4);

    for (int i = 2; i < argc; ++i) {
        FileTask task;
        task.path = argv[i];
        task.callback = [](const std::string& content) {
            std::lock_guard<std::mutex> lock(g_log_mutex);
            if (g_log_file && g_temp_buffer) {
                snprintf(g_temp_buffer, g_buffer_size,
                         "Processed %zu bytes", content.size());
                fprintf(g_log_file, "%s\n", g_temp_buffer);
            }
        };
        processor.submit(std::move(task));
    }

    while (!g_shutdown_requested.load()) {
        if (processor.is_idle()) break;
        usleep(100000);
    }

    log_message("Service shutting down");
    cleanup_resources();
    return 0;
}
